content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
}

body {
  background-color: #050508;
  color: #f0f0f5;
  overflow: hidden;
  width: 100vw;
  height: 100vh;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  background: radial-gradient(circle at center, #0f1026 0%, #050508 100%);
  overflow: hidden;
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.ui-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 10;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 20px;
}

.ui-overlay > * {
  pointer-events: auto;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(10, 10, 25, 0.7);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 15px 25px;
  border-radius: 12px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  background: linear-gradient(135deg, #ffcc00, #ff6600);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.header p {
  font-size: 0.85rem;
  color: #a0a0c0;
}

.controls-panel {
  display: flex;
  gap: 15px;
  align-items: center;
  background: rgba(10, 10, 25, 0.7);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 12px 20px;
  border-radius: 12px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  align-self: center;
  margin-bottom: 10px;
  flex-wrap: wrap;
  justify-content: center;
}

.speed-label {
  font-size: 0.9rem;
  color: #d0d0f0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.speed-label input[type="range"] {
  accent-color: #ff6600;
  cursor: pointer;
}

.btn {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
  padding: 8px 16px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: all 0.2s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.btn:hover {
  background: rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.4);
  transform: translateY(-1px);
}

.btn-active {
  background: linear-gradient(135deg, #ff6600, #cc3300);
  border-color: #ff6600;
  box-shadow: 0 0 15px rgba(255, 102, 0, 0.4);
}

.planet-info-card {
  position: absolute;
  top: 100px;
  right: 25px;
  width: 320px;
  background: rgba(10, 10, 25, 0.85);
  backdrop-filter: blur(15px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.6);
  z-index: 20;
  animation: fadeIn 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.planet-info-card h2 {
  font-size: 1.4rem;
  color: #ffffff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding-bottom: 8px;
}

.planet-info-card p {
  font-size: 0.9rem;
  color: #c0c0d0;
  line-height: 1.4;
}

.planet-info-card .info-row {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  background: rgba(255, 255, 255, 0.05);
  padding: 6px 10px;
  border-radius: 6px;
}

.planet-info-card .info-label {
  color: #9090b0;
}

.planet-info-card .info-value {
  color: #ffffff;
  font-weight: 500;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 768px) {
  .ui-overlay {
    padding: 10px;
  }
  .header {
    flex-direction: column;
    align-items: flex-start;
    gap: 5px;
    padding: 10px 15px;
  }
  .header h1 {
    font-size: 1.2rem;
  }
  .planet-info-card {
    top: auto;
    bottom: 80px;
    right: 10px;
    left: 10px;
    width: auto;
  }
  .controls-panel {
    width: 100%;
    padding: 10px;
    gap: 8px;
  }
}

export interface PlanetData {
  id: string;
  name: string;
  radius: number;
  distance: number;
  speed: number;
  color: string;
  mass: string;
  distanceFromSun: string;
  description: string;
}

export interface SimulationSettings {
  speedMultiplier: number;
  isPaused: boolean;
  selectedPlanetId: string | null;
}

import { FC } from 'react';
import { PlanetData } from '../types';

interface PlanetInfoProps {
  planet: PlanetData | null;
  onClose: () => void;
}

export const PlanetInfo: FC<PlanetInfoProps> = ({ planet, onClose }) => {
  if (!planet) return null;

  return (
    <div className="planet-info-card">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h2>{planet.name}</h2>
        <button className="btn" onClick={onClose} style={{ padding: '4px 8px', fontSize: '0.8rem' }}>
          ✕
        </button>
      </div>
      <p>{planet.description}</p>

      <div className="info-row">
        <span className="info-label">質量</span>
        <span className="info-value">{planet.mass}</span>
      </div>

      <div className="info-row">
        <span className="info-label">太陽からの距離</span>
        <span className="info-value">{planet.distanceFromSun}</span>
      </div>

      <div className="info-row">
        <span className="info-label">公転スピード</span>
        <span className="info-value">{planet.speed.toFixed(2)}x</span>
      </div>
    </div>
  );
};

export default PlanetInfo;

import { FC, useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Stars } from '@react-three/drei';
import * as THREE from 'three';
import { PlanetData, SimulationSettings } from '../types';

interface SolarSystemProps {
  planets: PlanetData[];
  settings: SimulationSettings;
  onSelectPlanet: (id: string) => void;
}

interface PlanetMeshProps {
  planet: PlanetData;
  settings: SimulationSettings;
  onSelect: (id: string) => void;
}

const PlanetObject: FC<PlanetMeshProps> = ({ planet, settings, onSelect }) => {
  const ref = useRef<THREE.Group>(null);
  const meshRef = useRef<THREE.Mesh>(null);
  const angleRef = useRef(Math.random() * Math.PI * 2);

  useFrame((_, delta) => {
    if (!settings.isPaused && ref.current) {
      // 公転
      angleRef.current += planet.speed * settings.speedMultiplier * delta * 0.2;
      const x = Math.cos(angleRef.current) * planet.distance;
      const z = Math.sin(angleRef.current) * planet.distance;
      ref.current.position.set(x, 0, z);
    }

    if (!settings.isPaused && meshRef.current) {
      // 自転
      meshRef.current.rotation.y += delta * 0.5 * settings.speedMultiplier;
    }
  });

  const isSelected = settings.selectedPlanetId === planet.id;

  return (
    <group ref={ref}>
      {/* 軌道円 */}
      <mesh rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[planet.distance - 0.05, planet.distance + 0.05, 64]} />
        <meshBasicMaterial color="#ffffff" transparent opacity={0.15} side={THREE.DoubleSide} />
      </mesh>

      {/* 惑星本体 */}
      <mesh
        ref={meshRef}
        onClick={(e) => {
          e.stopPropagation();
          onSelect(planet.id);
        }}
      >
        <sphereGeometry args={[planet.radius, 32, 32]} />
        <meshStandardMaterial
          color={planet.color}
          roughness={0.7}
          metalness={0.2}
          emissive={isSelected ? planet.color : '#000000'}
          emissiveIntensity={isSelected ? 0.5 : 0}
        />
      </mesh>
    </group>
  );
};

const Sun: FC = () => {
  const sunRef = useRef<THREE.Mesh>(null);

  useFrame((_, delta) => {
    if (sunRef.current) {
      sunRef.current.rotation.y += delta * 0.1;
    }
  });

  return (
    <mesh ref={sunRef}>
      <sphereGeometry args={[3, 32, 32]} />
      <meshBasicMaterial color="#ffaa00" />
      <pointLight intensity={2} distance={100} decay={0.5} color="#fff5e6" />
    </mesh>
  );
};

export const SolarSystem: FC<SolarSystemProps> = ({ planets, settings, onSelectPlanet }) => {
  return (
    <div className="canvas-container">
      <Canvas camera={{ position: [0, 25, 35], fov: 60 }}>
        <color attach="background" args={['#050508']} />
        <ambientLight intensity={0.1} />
        <Stars radius={100} depth={50} count={5000} factor={4} saturation={0} fade speed={1} />

        <Sun />

        {planets.map((planet) => (
          <PlanetObject
            key={planet.id}
            planet={planet}
            settings={settings}
            onSelect={onSelectPlanet}
          />
        ))}

        <OrbitControls enablePan enableZoom enableRotate maxDistance={100} minDistance={5} />
      </Canvas>
    </div>
  );
};

export default SolarSystem;

