export function App() {
  const [settings, setSettings] = useState<SimulationSettings>({
    speedMultiplier: 1,
    isPaused: false,
    selectedPlanetId: null,
  });

  const selectedPlanet = PLANETS_DATA.find((p) => p.id === settings.selectedPlanetId) || null;

  const handleTogglePause = () => {
    setSettings((prev) => ({ ...prev, isPaused: !prev.isPaused }));
  };

  const handleSpeedChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setSettings((prev) => ({ ...prev, speedMultiplier: val }));
  };

  const handleSelectPlanet = (id: string) => {
    setSettings((prev) => ({ ...prev, selectedPlanetId: prev.selectedPlanetId === id ? null : id }));
  };

  const handleCloseInfo = () => {
    setSettings((prev) => ({ ...prev, selectedPlanetId: null }));
  };

  return (
    <div className="app-container">
      <SolarSystem
        planets={PLANETS_DATA}
        settings={settings}
        onSelectPlanet={handleSelectPlanet}
      />

      <div className="ui-overlay">
        <header className="header">
          <div>
            <h1>3D 太陽系シミュレーション</h1>
            <p>惑星をクリックして詳細情報を表示できます</p>
          </div>
        </header>

        <div className="controls-panel">
          <button
            className={`btn ${settings.isPaused ? 'btn-active' : ''}`}
            onClick={handleTogglePause}
          >
            {settings.isPaused ? '▶ 再生' : '⏸ 一時停止'}
          </button>

          <div className="speed-label">
            <span>スピード: {settings.speedMultiplier.toFixed(1)}x</span>
            <input
              type="range"
              min="0.1"
              max="5"
              step="0.1"
              value={settings.speedMultiplier}
              onChange={handleSpeedChange}
            />
          </div>
        </div>
      </div>

      <PlanetInfo planet={selectedPlanet} onClose={handleCloseInfo} />
    </div>
  );
}

export default App;
